#include "संचारजाळे_द्विमानजोडणी.h"
static क्लाउड_संचारद्वार_पत्ता पत्ता(unsigned पॉर्ट_मूल्य) {
    क्लाउड_संचारद्वार_पत्ता मूल्य = {}; मूल्य.पत्ता_कुटुंब = क्लाउड_कुटुंब;
    मूल्य.पोर्ट_नंबर = संचारजाळे_लघु(पॉर्ट_मूल्य); मूल्य.इंटरनेट_पत्ता.पत्ता_मूल्य = संचारजाळे_पूर्णांक(स्वपरतावा_पत्ता); return मूल्य;
}
extern "C" int प्रारंभ_प्रयोक्ता_अनुप्रयोग(int) {
    int पाठवणे_संचारटोक = संचारटोक_तयार_करा(क्लाउड_कुटुंब, स्वतंत्रसंदेश_संचारद्वार, 0);
    int ग्राहक_संचारटोक = संचारटोक_तयार_करा(क्लाउड_कुटुंब, स्वतंत्रसंदेश_संचारद्वार, स्वतंत्रसंदेश_प्रोटोकॉल);
    if (पाठवणे_संचारटोक < 0 || ग्राहक_संचारटोक < 0) return 1;
    क्लाउड_संचारद्वार_पत्ता आगमन_मूल्य = पत्ता(7777), प्रस्थान_मूल्य = पत्ता(7778), पाठवलेले_पत्ता = {};
    संचारद्वार_पत्ता_लांबी_टाइप_करा पत्ता_लांबी = sizeof(पाठवलेले_पत्ता);
    if (बाइंड_करा_पत्ता(ग्राहक_संचारटोक, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य))) return 2;
    if (बाइंड_करा_पत्ता(पाठवणे_संचारटोक, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != -1 || त्रुटी_संख्या != 98) return 3;
    if (बाइंड_करा_पत्ता(पाठवणे_संचारटोक, (संचारद्वार_पत्ता *)&प्रस्थान_मूल्य, sizeof(प्रस्थान_मूल्य))) return 4;
    static const char सामुग्री_मूल्य[] = "한글 UDP loopback 😀";
    char स्वीकारलेले_मूल्य[64] = {};
    if (स्वतंत्रसंदेश_डेटा_पाठवा(पाठवणे_संचारटोक, सामुग्री_मूल्य, sizeof(सामुग्री_मूल्य), 0, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != sizeof(सामुग्री_मूल्य)) return 5;
    if (स्वतंत्रसंदेश_डेटा_स्वीकारा(ग्राहक_संचारटोक, (void *)सामुग्री_मूल्य, sizeof(सामुग्री_मूल्य), 0, 0, 0) != -1 || त्रुटी_संख्या != 14) return 6;
    if (स्वतंत्रसंदेश_डेटा_स्वीकारा(ग्राहक_संचारटोक, स्वीकारलेले_मूल्य, sizeof(स्वीकारलेले_मूल्य), 0, (संचारद्वार_पत्ता *)&पाठवलेले_पत्ता, &पत्ता_लांबी) != sizeof(सामुग्री_मूल्य)) return 7;
    if (पत्ता_लांबी != sizeof(पाठवलेले_पत्ता) || मोबाइल_क्रम_लघु(पाठवलेले_पत्ता.पोर्ट_नंबर) != 7778 || मोबाइल_क्रम_पूर्णांक(पाठवलेले_पत्ता.इंटरनेट_पत्ता.पत्ता_मूल्य) != स्वपरतावा_पत्ता) return 8;
    for (unsigned क्रमांक_अनुक्रमणिका = 0; क्रमांक_अनुक्रमणिका < sizeof(सामुग्री_मूल्य); क्रमांक_अनुक्रमणिका++) if (स्वीकारलेले_मूल्य[क्रमांक_अनुक्रमणिका] != सामुग्री_मूल्य[क्रमांक_अनुक्रमणिका]) return 9;
    if (स्वतंत्रसंदेश_डेटा_स्वीकारा(ग्राहक_संचारटोक, स्वीकारलेले_मूल्य, sizeof(स्वीकारलेले_मूल्य), 0, 0, 0) != -1 || त्रुटी_संख्या != 11) return 10;
    if (स्वतंत्रसंदेश_डेटा_पाठवा(ग्राहक_संचारटोक, स्वीकारलेले_मूल्य, sizeof(सामुग्री_मूल्य), 0, (संचारद्वार_पत्ता *)&पाठवलेले_पत्ता, sizeof(पाठवलेले_पत्ता)) != sizeof(सामुग्री_मूल्य)) return 11;
    if (स्वतंत्रसंदेश_डेटा_स्वीकारा(पाठवणे_संचारटोक, स्वीकारलेले_मूल्य, 4, 0, 0, 0) != 4) return 12;
    if (स्वतंत्रसंदेश_डेटा_स्वीकारा(पाठवणे_संचारटोक, स्वीकारलेले_मूल्य, 4, 0, 0, 0) != -1 || त्रुटी_संख्या != 11) return 13;
    for (int क्रमांक_अनुक्रमणिका = 0; क्रमांक_अनुक्रमणिका < 4; क्रमांक_अनुक्रमणिका++) if (स्वतंत्रसंदेश_डेटा_पाठवा(पाठवणे_संचारटोक, सामुग्री_मूल्य, sizeof(सामुग्री_मूल्य), 0, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != sizeof(सामुग्री_मूल्य)) return 14;
    if (स्वतंत्रसंदेश_डेटा_पाठवा(पाठवणे_संचारटोक, सामुग्री_मूल्य, sizeof(सामुग्री_मूल्य), 0, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != -1 || त्रुटी_संख्या != 11) return 15;
    for (int क्रमांक_अनुक्रमणिका = 0; क्रमांक_अनुक्रमणिका < 4; क्रमांक_अनुक्रमणिका++) if (स्वतंत्रसंदेश_डेटा_स्वीकारा(ग्राहक_संचारटोक, स्वीकारलेले_मूल्य, sizeof(स्वीकारलेले_मूल्य), 0, 0, 0) != sizeof(सामुग्री_मूल्य)) return 16;
    if (स्वतंत्रसंदेश_डेटा_पाठवा(पाठवणे_संचारटोक, 0, 0, 0, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != 0 ||
        स्वतंत्रसंदेश_डेटा_स्वीकारा(ग्राहक_संचारटोक, 0, 0, 0, 0, 0) != 0) return 21;
    आगमन_मूल्य.इंटरनेट_पत्ता.पत्ता_मूल्य = संचारजाळे_पूर्णांक(0x08080808);
    if (स्वतंत्रसंदेश_डेटा_पाठवा(पाठवणे_संचारटोक, सामुग्री_मूल्य, sizeof(सामुग्री_मूल्य), 0, (संचारद्वार_पत्ता *)&आगमन_मूल्य, sizeof(आगमन_मूल्य)) != -1 || त्रुटी_संख्या != 101) return 17;
    if (संचारटोक_तयार_करा(क्लाउड_कुटुंब, प्रवाह_संचारजाळे, स्वतंत्रसंदेश_प्रोटोकॉल) != -1 || त्रुटी_संख्या != 93) return 18;
    पत्ता_लांबी = sizeof(पाठवलेले_पत्ता);
    if (संचारद्वार_पत्ता_वाचा(ग्राहक_संचारटोक, (संचारद्वार_पत्ता *)&पाठवलेले_पत्ता, &पत्ता_लांबी) || मोबाइल_क्रम_लघु(पाठवलेले_पत्ता.पोर्ट_नंबर) != 7777) return 19;
    if (संचिका_मिटवा(ग्राहक_संचारटोक) || संचिका_मिटवा(ग्राहक_संचारटोक) != -1 || त्रुटी_संख्या != 9) return 20;
    // 보내는곳은 열어 둔다: निर्गमन_करा_अनुप्रयोग 시 프로세스별 socket 정리를 검사한다.
    static const char आहे_पूर्ण[] = "EL0 UDP LOOPBACK PASS (external network unavailable)\n";
    संचिका_डेटा_लिहा(1, आहे_पूर्ण, sizeof(आहे_पूर्ण) - 1);
    return 0;
}
